.sb-wf--login { min-width: 1100px; height: 100%; }
.sb-wf--login .sb-wf-nav-panel { width: 200px; display: flex; flex-direction: column; min-height: 540px; height: 100%; }
.sb-wf--login .sb-wf-nav-scroll { flex: 1; display: flex; flex-direction: column; }
.sb-wf-login-main { flex: 1; display: flex; min-height: 540px; min-width: 0; height: 100%; }
.sb-wf-login-promo { flex: 1.15; display: flex; flex-direction: column; padding: 36px 32px 28px; background: linear-gradient(135deg, #f5f3ff 0%, #faf5ff 40%, #f8fafc 100%); border-right: 1px solid #e2e8f0; }
.sb-wf-login-form-col { flex: 0 0 400px; display: flex; align-items: center; justify-content: center; padding: 28px 24px; background: #f1f5f9; }
.sb-wf-login-card { width: 100%; max-width: 340px; background: #fff; border: 1px solid #e2e8f0; border-radius: 12px; padding: 28px 24px 24px; }
.sb-wf-login-card-head { margin-bottom: 20px; }
.sb-wf-login-card-head .sb-wf-text--h1 { font-size: 15px; margin-bottom: 6px; }
.sb-wf-field { margin-bottom: 14px; }
.sb-wf-field label { display: block; font-size: 10px; font-weight: 600; color: #475569; margin-bottom: 5px; }
.sb-wf-input { display: flex; align-items: center; padding: 9px 12px; border: 1px solid #e2e8f0; border-radius: 8px; background: #fafbfc; font-size: 11px; color: #94a3b8; min-height: 36px; }
.sb-wf-input--pw { justify-content: space-between; }
.sb-wf-form-row { display: flex; justify-content: space-between; align-items: center; margin: 4px 0 16px; font-size: 10px; }
.sb-wf-check { display: flex; align-items: center; gap: 6px; color: #64748b; }
.sb-wf-check-box { width: 14px; height: 14px; border: 2px solid #cbd5e1; border-radius: 3px; background: #fff; flex-shrink: 0; }
.sb-wf-link { color: #6366f1; font-weight: 600; cursor: default; }
.sb-wf-divider { display: flex; align-items: center; gap: 10px; margin: 18px 0 14px; font-size: 10px; color: #94a3b8; }
.sb-wf-divider::before, .sb-wf-divider::after { content: ''; flex: 1; height: 1px; background: #e2e8f0; }
.sb-wf-social { display: flex; flex-direction: column; gap: 8px; }
.sb-wf-social .sb-wf-btn { justify-content: flex-start; gap: 10px; padding: 10px 14px; border-radius: 8px; width: 100%; background: #fff; }
.sb-wf-social-icon { width: 22px; height: 22px; border-radius: 4px; display: flex; align-items: center; justify-content: center; font-size: 11px; font-weight: 800; flex-shrink: 0; }
.sb-wf-social-icon--naver { background: #03c75a; color: #fff; }
.sb-wf-social-icon--kakao { background: #fee500; color: #3c1e1e; }
.sb-wf-social-icon--google { background: #fff; border: 1px solid #e2e8f0; color: #4285f4; }
.sb-wf-login-footer { margin-top: 18px; text-align: center; font-size: 10px; color: #64748b; }
.sb-wf-stat-row { display: grid; grid-template-columns: repeat(4, 1fr); gap: 10px; margin-top: auto; padding-top: 24px; }
.sb-wf-stat-card { border: 1px solid #e2e8f0; border-radius: 8px; padding: 12px 8px; background: rgba(255,255,255,.75); text-align: center; }
.sb-wf-stat-card .sb-wf-block--icon { margin: 0 auto 6px; width: 32px; height: 32px; }
.sb-wf-stat-card .sb-wf-text { font-size: 10px; font-weight: 700; color: #334155; line-height: 1.35; }
.sb-wf-nav-bottom-item { margin-top: auto; padding-top: 12px; border-top: 1px solid #e2e8f0; }
.sb-wf-btn--primary { background: #6366f1; border-color: #6366f1; color: #fff; }
.sb-wf-visual { min-height: 220px; display: flex; flex-direction: column; }
.sb-wf-visual-img { flex: 1; min-height: 200px; background: #f1f5f9; border: 1px solid #e2e8f0; border-radius: 8px; display: flex; flex-direction: column; align-items: center; justify-content: center; gap: 6px; color: #94a3b8; font-size: 11px; font-weight: 600; text-align: center; padding: 16px; }
.sb-wf-visual-img::before { content: '✕ VISUAL'; font-size: 13px; font-weight: 700; color: #64748b; }
